code_templates.solution_code:
#include <iostream>
using namespace std;

void promotion(int *megabytes ) {
    
    int multiplier;
    cin>>multiplier;
    *megabytes =multiplier * *megabytes;
    
    
}

int main() {
    int megabytes;
    cin >> megabytes;
    
    cout << "提升前: " << megabytes << endl;
    
    promotion(&megabytes );
    
    cout << "提升后: " << megabytes << endl;
    
    return 0;
}

